INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('451402d0-d845-40ca-bbb6-14e4361a828a', 'Late Fees', '6', '2', 'INTERESES MORATORIOS', E'- Si la Subarrendataria no paga a tiempo la Renta Mensual, la Cuota de Mantenimiento, o cualquier otro pago requerido por el contrato, deberá pagar intereses por retraso.\n- Los intereses se calculan desde la fecha en que debió hacerse el pago hasta que se realice efectivamente.\n- La tasa de interés por retraso es tres veces la Tasa de Interés Interbancaria de Equilibrio a 28 días (TIIE), determinada por el Banco de México, dividida entre 12.\n- Se utiliza la TIIE vigente al inicio del retraso o, si no está disponible, la más cercana a esa fecha.\n- Los intereses se calculan mensualmente, incluso si el retraso es solo de un día.', 'En caso de que la Subarrendataria no cubra puntualmente la Renta Mensual, la Cuota de Mantenimiento a que se refiere la cláusula Décimo Cuarta y cualesquiera otros pagos a que esté obligada conforme al presente Contrato, deberá cubrir intereses moratorios calculados a partir de la fecha en que debió haberse realizado el pago que corresponda y hasta la fecha en que efectivamente se haga el pago respectivo, a la tasa de interés que resulte de multiplicar por 3 (tres), la Tasa de Interés Interbancaria de Equilibrio a 28 (veintiocho) días ("TIIE"), o la que la sustituya, en su caso, determinada por el Banco de México, y dividirla entre 12 (doce), por cada mes o fracción de mes que dure la mora. La tasa TIIE que se utilizará será la que haya determinado Banco de México en la fecha del inicio de la mora, o a falta de esta, la previa más cercana a dicha fecha. El cómputo de los intereses moratorios se hará por períodos mensuales, no obstante que la morosidad corresponda a un sólo día.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('451402d0-d845-40ca-bbb6-14e4361a828a', 'Incremento de Renta', '6', '2', 'INCREMENTO A LA RENTA FIJA', E'- The fixed rent will increase annually on the anniversary of the rent payment start date.\n- The increase is based on the inflation rate, calculated by comparing the National Consumer Price Index (INPC) of the current month with the same month of the previous year.\n- The new fixed rent amount will apply for the next 12 months.\n- For the first 5 years of the contract, the rent increase is capped at 8% per year.', E'Las Partes convienen que la Renta Fija se incrementará de forma anual en cada aniversario de la Fecha de Inicio de Pago de Renta, en el porcentaje de inflación resultante de comparar el Índice Nacional de Precios al Consumidor ("INPC"), del mes correspondiente del año anterior con el INPC publicado en la fecha más cercana a la fecha de incremento. El resultado total de la operación anterior será la Renta Fija vigente para los siguientes 12 (doce) meses y así sucesivamente año con año.\n\nLas Partes Convienen que el Incremento a la Renta Fija estará topado al 8% (ocho por ciento) únicamente durante los primeros 5 (cinco) años de Plazo de Vigencia del presente Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('451402d0-d845-40ca-bbb6-14e4361a828a', 'Percentage Rent', '5', '2', 'RENTA VARIABLE', E'- Starting from the Rent Payment Start Date, the Subtenant must calculate their net income from the previous month within the first 10 days of each month. This includes all sales made at the premises, excluding VAT, regardless of documentation.\n- If 8% of the Net Income is greater than the Fixed Rent, the difference is considered Variable Rent.\n- The Subtenant must pay this Variable Rent to the Sublandlord within 5 days of calculating the Net Income, without any deductions, and including the applicable VAT.', E'A partir de la Fecha de Inicio de Pago de Renta, la Subarrendataria se obliga a calcular, dentro de los primeros 10 (diez) días naturales de cada mes, los ingresos netos que haya obtenido durante el mes inmediato anterior, por la venta de mercancías, bienes o servicios en el Local, restando el IVA que corresponda, considerando todas y cada una de las ventas realizadas en el Local, sin importar que existan comprobantes, recibos u otro documento que pudieran acreditar la venta o prestación del servicio en un lugar distinto al Local (los "Ingresos Netos").\n\nEn caso de que el 8% (ocho por ciento) de los Ingresos Netos resulte mayor a la Renta Fija, dicha diferencia se considerará como renta variable (la “Renta Variable"), misma que la Subarrendataria deberá pagar a la Subarrendadora, sin que medie requerimiento alguno y sin deducciones, compensaciones o reducciones, dentro de los 5 (cinco) días naturales siguientes a la fecha en que se haya realizado el cálculo de los Ingresos Netos, más el IVA correspondiente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('451402d0-d845-40ca-bbb6-14e4361a828a', 'Common Area Maintenance Charges', '23', '14', 'MANTENIMIENTO Y OPERACIÓN DEL CENTRO COMERCIAL', E'- The Subtenant must pay a monthly maintenance fee to the Sublandlord starting from the Rent Payment Start Date.\n- This fee covers the maintenance of common areas, equipment, and facilities in the Shopping Center.\n- The maintenance fee is included in the monthly Fixed Rent.\n- The maintenance fee will increase annually as outlined in Clause Two regarding the increase of Fixed Rent.', 'La Subarrendataria se obliga a pagar mensualmente a la Subarrendadora a partir de la Fecha de Inicio de Pago de Renta, por concepto de cuota por gastos de mantenimiento de las áreas comunes, equipos e instalaciones comunes del Centro Comercial, misma que se incluye en la Renta Fija mensual (la “Cuota de Mantenimiento") en el entendido de que la Cuota de Mantenimiento será incrementada anualmente de conformidad con lo establecido en la cláusula Segunda, sobre incremento de Renta Fija.');
