ico 06250","map_addr_1":"88 Calzada De La Ronda","map_addr_2":"Subancla 1","map_city_state_zip":"Ex Hipódromo, Cuauhtémoc, Ciudad de México 06250","grid_brand":"Planet Fitness","location_created_at":"2025-09-29 15:42:19","active_lease_count_over_time":51128,"location_count_over_time":57819,"remaining_rent_liability_over_time":51128}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'dac11956-77dc-457f-af4d-a6c926cb57e9', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Tlatelolco Sublease: Tiendas Soriana, S.A. De C.V. (09/02/2023 - 09/01/2033)', NULL, true, 'activo', 'Lease', NULL, '2023-09-02', '2023-01-23', '2033-09-01', '2043-09-01', false, 2, NULL, 2, NULL, NULL, '2033-07-03', 'Send Notice to Exercise or Decline', 119, 'Tiendas Soriana, S.A. De C.V.', NULL, NULL, '3102 Avenida Alejandro De Rodas', 'A', 'Monterrey', 'MX-NLE', '64610', 'MX', 'Marcela Pérez Olivas', '818-329-9048', NULL, 150, 'percent', NULL, NULL, 900000, 'Con fecha 29 de junio del 2023 EL SUBARRENDATARIO pagó a a SORIANA 3 meses de rentas adelantadas con base a la contraprestación pactada en la cláusula inmediata anterior, lo que equivale a la cantidad total de $900,000.00 (novecientos mil pesos 00/100 M.N.) más el correspondiente impuesto al valor agregado que en su momento llegare a substituirle, por concepto de rentas anticipadas, mismo que fueron aplicados a los meses de renta de septiembre, octubre y noviembre del 2023', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'Domicilio del Contrato', E'Calzada de la Ronda No 88 Colonia Ex Hipódromo C.P. 06250 Cuauhtémoc Ciudad de Mexico\nLocal Comercial Subancla 1', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'Lease note', 'Se condonó $85,018.75 dentro de la Renta Mensual de noviembre del 2024', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'Fecha de Firma del Contrato', '28 de septiembre de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'Fecha de Apertura', '9 de febrero de 2023', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'Incremento de Renta', '1', '6', 'AUMENTO DE RENTA', E'- The monthly sublease payment for the commercial area will increase annually every January.\n- The first increase will occur in January 2025.\n- The increase will match the rise in the National Consumer Price Index published by INEGI or any replacement index measuring inflation in Mexico.\n- Annual increases cannot exceed 8% of the current payment amount.', 'El importe de la contraprestación mensual por subarrendamiento de EL ÁREA COMERCIAL se incrementará Anualmente, durante los meses de enero de cada año, siendo el primer incremento hasta el mes de enero del año 2025, en la misma proporción en que aumente el indice Nacional de Precios al Consumidor que publique el INEGI (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% del valor de la contraprestación vigente que opere en dicho periodo."');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'Common Area Maintenance Charges', '4', '4', 'CONTRAPRESTACIÓN', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent.\n- This fee starts when the business begins operations in the commercial area.\n- The fee will include applicable value-added tax (VAT) or any future equivalent tax.\n- The subtenant will not contribute to the shopping center''s advertising expenses.', 'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo. Las Partes convienen que EL SUBARRENDATARIO no participará en los gastos de Publicidad del Centro Comercial por lo que no se generará cantidad alguno por concepto de publicidad a cargo de éste.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f110b891-fb84-42ec-80e8-e3f78cd35651', 'Late Fees', '4', '4', 'CONTRAPRESTACIÓN', E'- If payment is late by more than 10 days, late interest will be added to the unpaid balance.\n- The late interest rate is three times the Interbank Equilibrium Interest Rate published by Banxico, spread over the time of delay.\n- If there are unpaid rents or interest, any payment made will first cover the interest, and the rest will go towards the rent owed.\n- If rent is not paid within the first 10 days of the month, a 4% monthly late interest will be added, spread over the time of delay.\n- Payments will first cover interest, then any remaining amount will go towards the rent owed.', E'A partir del onceavo día se acumularán al saldo insoluto, intereses moratorios, calculados a razón de la tasa anualizada que resulte de multiplicar por 3 (tres) la TASA DE INTERES INTERBANCARIA DE EQUILIBRIO, publicada mensualmente por Banxico, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.\n\nEn caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('da7bf58b-8b6a-49d6-ba2f-5044db57e181', 'Paseo Tollocan', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '600 Avenida Paseo Tollocan', 'Subancla 1', 'Toluca', 'Mexico', '50150', 'MX', '600 Avenida Paseo Tollocan, Subancla 1, Toluca, Mexico 50150', 19.282182, -99.641101, 'Retail', 'Lifestyle Center', 'Sports & Recreation', 'Franchise', 'Paseo Tollocan', 1911.09, 1911.09, NULL, '{"map_lease_expiration_date":"2032-08-14","map_marker_color":"#A879D2","coordinate":"rooftop|19.2821820000|-99.6411010000|accurate","city_state":"Toluca, Mexico","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"506 Calle Juan Ignacio Ramón, Monterrey, MX-NLE 64000","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2037-08-14","lease_expiration_date":"2032-08-14","lease_renewal_notice":"60 Days Prior","lease_length_in_months_remaining":70,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57821,"grid_name":"Paseo Tollocan","grid_full_address":"600 Avenida Paseo Tollocan, Subancla 1, Toluca, Mexico 50150","map_addr_1":"600 Avenida Paseo Tollocan","map_addr_2":"Subancla 1","map_city_state_zip":"Toluca, Mexico 50150","grid_brand":"Planet Fitness","location_created_at":"2025-09-29 16:20:53","active_lease_count_over_time":51131,"location_count_over_time":57821,"remaining_rent_liability_over_time":51131}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'da7bf58b-8b6a-49d6-ba2f-5044db57e181', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Paseo Tollocan Sublease: Inmuebles Jax, S.A. De C.V. (08/15/2022 - 08/14/2032)', NULL, true, 'activo', 'Lease', NULL, '2023-10-01', '2023-02-01', '2032-08-14', '2041-08-14', false, 2, NULL, 2, NULL, NULL, '2032-06-15', 'Send Notice to Renew', 119, 'Inmuebles Jax, S.A. De C.V.', NULL, NULL, '506 Calle Juan Ignacio Ramón', NULL, 'Monterrey', 'MX-NLE', '64000', 'MX', 'Cesar Alejandro Martinez Guerrero', NULL, NULL, 152, 'percent', NULL, NULL, 611520, '"LA SUBARRENDATARIA" deberá de pagar a la firma del presente contrato, el importe de 2 (dos) meses de RENTA MENSUAL, equivalente a $611,520.00 (Seiscientos once mil quinientos veinte pesos 00/100 M.N.), más IVA (Impuesto al Valor Agregado), y el equivalente a un mes de renta, es decir la cantidad de $305,760.00 (Trescientos cinco mil setecientos sesenta pesos 00/100 M.N.) previos a la entrega del Inmueble, los cuales se aplicarán automáticamente, a los meses de renta seis, doce dieciocho mismos que serán aplicables en el momento que se genere la obligación de pago de dicha renta atendiendo el periodo de gracia establecido en el presente contrato.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Amendment', E'LAS PARTES manifiestan que por el reforzamiento estructural de la techumbre del INMUEBLE requerido por Protección Civil del Estado de México al SUBARRENDADOR realizado del 17 de diciembre de 2024 y concluido el 5 de enero de 2025 (en lo sucesivo la "OBRA") Y como compensación por el cierre del INMUEBLE durante el tiempo que se realizó la OBRA, el SUBARRENDADOR adeuda a la SUBARRENDATARIA la cantidad de $787,080.00 (Setecientos ochenta y siete mil ochenta pesos 00/100 M.N.).\n\n1. El SUBARRENDATARIO NO pagará la RENTA MENSUAL descrita en la Cláusula Octava de EL CONTRATO a partir del mes de abril y mayo del presente año y volverá а pagar la RENTA MENSUAL a partir del mes de junio de 2025. \n2. La RENTA MENSUAL del mes de junio de 2025 será proporcional y será por la cantidad de $168,634.02 (Ciento sesenta y ocho mil seiscientos treinta y cuatro pesos 02/100 M.N.) más el Impuesto al Valor Agregado. \n3. A partir del mes de julio de 2025, la SUBARRENDATARIA pagará la RENTA MENSUAL establecida en la Cláusula Octava de EL CONTRATO.\n\nEl SUBARRENDADOR garantiza la OBRA y la reparación de cualquier daño por cualquier vicio oculto por un periodo de 6 (seis) meses contados a partir de la conclusión de la OBRA del INMUEBLE.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Lease note', 'Se ejerció una prórroga de 90 días del periodo de gracia', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Vigencia', 'La segunda prórroga de la vigencia del contrato es de 4 años y 6 meses', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Domicilio del Contrato', E'Paseo Tollocan 600, colonia Progreso, C.P. 50150, Municipio de Toluca, Estado de México\nLocal identificado como Subancla 1', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Fecha de Firma del Contrato', '15 de agosto de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Fecha de Apertura', '11 de noviembre de 2023', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Late Fees', '13', '8', 'RENTA Y FORMA DE PAGO', E'- If the subtenant doesn''t pay the monthly rent on time, they will be charged a penalty.\n- The penalty is 5% of the unpaid rent balance.\n- This penalty applies for each month the rent remains unpaid until the full amount is paid.', 'La falta de pago puntual de la RENTA MENSUAL de que se trate, generará a cargo de LA SUBARRENDATARIA una pena convencional equivalente al 5% (cinco por ciento) sobre el saldo insoluto de la RENTA MENSUAL, por cada mes de retraso en el pago de la RENTA MENSUAL hasta en tanto dicho saldo insoluto no sea pagada en su totalidad.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b15ed334-92c7-4738-a3bf-9f559ccaea47', 'Incremento de Renta', '13', '8', 'RENTA Y FORMA DE PAGO', E'- Después de un año desde el inicio del pago de la renta, y cada año después, la renta mensual aumentará según el porcentaje de incremento del Índice Nacional de Precios al Consumidor (INPC) del último año.\n- El aumento no puede ser mayor al 10%.\n- Si el incremento es superior al 16%, las partes se reunirán para acordar el nuevo monto de la renta.', 'Transcurrido un año a partir de la Fecha de Inicio de Pago de la Renta y posteriormente de manera anual, la RENTA MENSUAL serán incrementadas anualmente en el mismo porcentaje de incremento que se haya registrado durante los últimos 12 (doce) meses inmediatos anteriores, el Índice Nacional de Precios al Consumidor (INPC) que publica el Instituto Nacional de Estadísticas y Geografía (INEGI). En la inteligencia de que dichos aumentos no podrán ser mayores al 10%. Las partes acuerdan que si dicho incremento sea superior al 16%, Las Partes se reunirán y determinarán de común acuerdo el monto de la renta.');
